code_guidance:
BREAK-BEFORE-MAKE, exact sequence:

static inline void cs_barrier(void) { __asm__ volatile("dsb" ::: "memory"); }

void cs_deselect_all(void) {
    digitalWriteFast(CS_EN, LOW);       // G1/E3 low -> ALL Y0..Y7 driven HIGH
    cs_barrier();
    delayNanoseconds(CS_SETTLE_NS);     // >= tpd(enable->Y) + slave /CS recovery
}

void cs_select(uint8_t ch) {            // ch = 0..7
    // 1. BREAK. Deselect BEFORE touching the address. This is the whole point.
    digitalWriteFast(CS_EN, LOW);
    cs_barrier();
    delayNanoseconds(CS_SETTLE_NS);     // >= tpd(enable->Y): 195 ns bound / 39 ns @4.5V

    // 2. Change the address only while globally deselected.
    //    Decode glitches here are invisible: all outputs are held HIGH by the enable.
    digitalWriteFast(CS_A, (ch >> 0) & 1u);
    digitalWriteFast(CS_B, (ch >> 1) & 1u);
    digitalWriteFast(CS_C, (ch >> 2) & 1u);
    cs_barrier();
    delayNanoseconds(CS_SETTLE_NS);     // >= tpd(A,B,C->Y): 225 ns bound / 45 ns @4.5V

    // 3. MAKE.
    digitalWriteFast(CS_EN, HIGH);
    cs_barrier();
    delayNanoseconds(CS_SETTLE_NS);     // >= tpd(enable->Y) before the first SCK edge
}

NEVER write the address while CS_EN is HIGH. There is no legal ordering that avoids glitches other than this one.
